import { BooleanColumn, ConditionsColumn, ReferenceColumn, StringColumn, Table } from '../../../db'

export const sys_atf_test_suite = Table({
    name: 'sys_atf_test_suite',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true, default: true }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: false,
            active: true,
            maxLength: 1000,
            dropdown: 'none',
        }),
        input_filter: ConditionsColumn({
            mandatory: false,
            label: 'Filter',
            read_only: false,
            active: true,
        }),
        name: StringColumn({
            mandatory: true,
            label: 'Name',
            read_only: false,
            active: true,
            default: 'My New Test Suite',
            maxLength: 100,
            dropdown: 'none',
        }),
        parent: ReferenceColumn({
            mandatory: false,
            label: 'Parent',
            read_only: false,
            active: true,
            referenceTable: 'sys_atf_test_suite',
        }),
        sn_atf_tg_generated: BooleanColumn({
            mandatory: false,
            label: 'Generated',
            read_only: true,
            active: true,
            default: false,
        }),
    },
})
